INSERT INTO supplier_catalog_offering (tenant_id, supplier_id, variant_id, supplier_sku_code, price_amount, currency_code, is_vat_inclusive, status, product_type, is_deleted)
SELECT ins.tenant_id, s.id, v.id, ins.supplier_sku_code, ins.price_amount::numeric, 'ILS'::text, false, 'active'::text, ins.product_type, false
FROM ins
JOIN suppliers s ON s.tenant_id = ins.tenant_id AND s.name = ins.supplier_name
JOIN lens_variant v ON v.display_id = ins.variant_display_id AND v.owner_tenant_id IS NULL
ON CONFLICT (supplier_id, variant_id, tenant_id) DO UPDATE SET updated_at=now(), price_amount=EXCLUDED.price_amount;
